<script setup>
import {onMounted,reactive,ref} from 'vue';
import Icon from '../Icon.vue';
import Modal from '../Modal.vue';
import {api,money,state,notify} from '../../lib';
const menus=ref([]),loading=ref(true),busy=ref(false),error=ref(''),formError=ref(''),editing=ref(null),deleting=ref(null),form=reactive({});
async function load(){loading.value=true;error.value='';try{menus.value=await api('/menu');}catch(e){error.value=e.message;}finally{loading.value=false;}}
onMounted(load);
function edit(item){Object.assign(form,item||{name:'',category:'makanan',price:15000,description:'',image_url:'',best_seller:false,spicy:false,available:true,calories:null});editing.value=item?.id||'new';formError.value='';}
async function save(){busy.value=true;formError.value='';try{const body={...form,calories:form.calories===''?null:form.calories};await api(editing.value==='new'?'/admin/menu':`/admin/menu/${editing.value}`,{method:editing.value==='new'?'POST':'PUT',body});editing.value=null;await load();notify('Menu berhasil disimpan.');}catch(e){formError.value=e.message;}finally{busy.value=false;}}
async function availability(item){busy.value=true;error.value='';try{await api(`/admin/menu/${item.id}/availability`,{method:'PATCH',body:{available:!item.available}});await load();notify('Ketersediaan menu diperbarui.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function remove(){busy.value=true;formError.value='';try{await api(`/admin/menu/${deleting.value.id}`,{method:'DELETE'});deleting.value=null;await load();notify('Menu dihapus dari katalog.');}catch(e){formError.value=e.message;}finally{busy.value=false;}}
</script>
<template><div class="admin-toolbar"><span class="muted">{{menus.length}} menu di katalog</span><div class="toolbar-actions"><button class="button secondary" @click="load" :disabled="loading"><Icon name="RefreshCw" :size="16"/>Refresh</button><button v-if="state.user.role==='owner'" class="button primary" @click="edit(null)"><Icon name="Plus" :size="17"/>Tambah menu</button></div></div><div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="loading" class="skeleton table-skeleton"></div><div v-else-if="!menus.length" class="panel empty-state"><Icon name="UtensilsCrossed" :size="35"/><h2>Katalog masih kosong</h2><p>Owner dapat menambahkan menu pertama.</p></div><div v-else class="table-wrap"><table><thead><tr><th>Menu</th><th>Kategori</th><th>Harga</th><th>Ketersediaan</th><th>Aksi</th></tr></thead><tbody><tr v-for="item in menus" :key="item.id"><td><div class="table-product"><img :src="item.image_url||'/favicon.svg'" :alt="item.name"/><div><strong>{{item.name}}</strong><small>{{item.best_seller?'Favorit Teras':'Menu reguler'}} · {{item.spicy?'Pedas':'Tidak pedas'}}</small></div></div></td><td class="capitalize">{{item.category}}</td><td class="nowrap">{{money(item.price)}}</td><td><button :class="['availability-toggle',{on:item.available}]" :disabled="busy" @click="availability(item)" :aria-label="`${item.name}: ${item.available?'tersedia, tandai habis':'habis, tandai tersedia'}`"><span></span>{{item.available?'Tersedia':'Habis'}}</button></td><td><div v-if="state.user.role==='owner'" class="row-actions"><button class="icon-button" :aria-label="'Ubah '+item.name" @click="edit(item)"><Icon name="Pencil" :size="17"/></button><button class="icon-button danger" :aria-label="'Hapus '+item.name" @click="deleting=item;formError=''"><Icon name="Trash2" :size="17"/></button></div><span v-else class="muted small">Kelola ketersediaan</span></td></tr></tbody></table></div>
<Modal v-if="editing" :title="editing==='new'?'Tambah menu':'Ubah menu'" @close="editing=null"><form @submit.prevent="save"><label>Nama menu<input v-model="form.name" required minlength="2" maxlength="100"/></label><div class="form-grid"><label>Kategori<select v-model="form.category"><option value="makanan">Makanan</option><option value="minuman">Minuman</option><option value="camilan">Camilan</option></select></label><label>Harga (Rp)<input v-model.number="form.price" type="number" min="100" max="10000000" step="100" required/></label></div><label>Deskripsi<textarea v-model="form.description" maxlength="400" rows="3"></textarea></label><label>URL foto<input v-model="form.image_url" placeholder="https://… atau /images/kopi.jpg" maxlength="1200"/><small>Gunakan foto HTTPS atau gambar dalam folder public/images.</small></label><label>Kalori perkiraan (kkal, opsional)<input v-model.number="form.calories" type="number" min="0" max="10000"/></label><div class="checkboxes"><label><input v-model="form.available" type="checkbox"/>Tersedia</label><label><input v-model="form.best_seller" type="checkbox"/>Favorit Teras</label><label><input v-model="form.spicy" type="checkbox"/>Pedas</label></div><p v-if="formError" class="alert error" role="alert">{{formError}}</p><div class="modal-actions"><button type="button" class="button secondary" @click="editing=null">Batal</button><button class="button primary" :disabled="busy">{{busy?'Menyimpan…':'Simpan menu'}}</button></div></form></Modal>
<Modal v-if="deleting" title="Hapus menu?" @close="deleting=null"><p>Menu <strong>{{deleting.name}}</strong> akan dihapus dari katalog. Rincian pada pesanan lama tetap tersimpan.</p><p v-if="formError" class="alert error" role="alert">{{formError}}</p><div class="modal-actions"><button class="button secondary" @click="deleting=null">Batal</button><button class="button danger-button" :disabled="busy" @click="remove">Hapus menu</button></div></Modal>
</template>
